select
  'introduction-to-anthropology',
  null,
  'Introduction to Anthropology',
  'Introduction to Anthropology',
  'This course introduces anthropology as the holistic and comparative study of humanity. Students explore cultural anthropology, biological anthropology, archaeology, linguistic anthropology, ethnographic methods, ethics, human evolution, material culture, language, kinship, religion, gender, race, colonialism, globalization, health, environment, digital life, and applied anthropology. The course emphasizes cultural relativism, evidence, fieldwork, ethical responsibility, and the public value of anthropological thinking.',
  $inanjson${"slug": "introduction-to-anthropology", "title": "Introduction to Anthropology", "description": "This course introduces anthropology as the holistic and comparative study of humanity. Students explore cultural anthropology, biological anthropology, archaeology, linguistic anthropology, ethnographic methods, ethics, human evolution, material culture, language, kinship, religion, gender, race, colonialism, globalization, health, environment, digital life, and applied anthropology. The course emphasizes cultural relativism, evidence, fieldwork, ethical responsibility, and the public value of anthropological thinking.", "topics": [{"id": "e8d86dbb-a0fa-4ffb-9a06-94d5586de5ca", "type": "topic", "title": "Anthropology as a Holistic, Comparative Study of Humanity", "description": "This opening unit gives students the map of the field. They learn that anthropology asks big questions about humanity by combining culture, biology, language, material evidence, history, and fieldwork.", "children": [{"id": "883b14fa-755c-496f-ae71-60094072b38a", "type": "subtopic", "title": "The Four-Field Frame", "children": [{"id": "2331408e-3347-4b39-a2fc-d76366b4a359", "type": "concept", "title": "Cultural anthropology"}, {"id": "7ff13121-3a94-429d-af12-b083e3858080", "type": "concept", "title": "Biological or physical anthropology"}, {"id": "5b161910-ce6d-46a6-b0b0-a727e3667d4c", "type": "concept", "title": "Archaeology"}, {"id": "ee323cba-ba37-4961-8a01-cdb14ad9d09f", "type": "concept", "title": "Linguistic anthropology"}], "description": "Students learn how cultural, biological, archaeological, and linguistic anthropology work together."}, {"id": "ee368664-5283-4a48-8549-f5ee2ceca4eb", "type": "subtopic", "title": "Holism and Comparison", "children": [{"id": "2dc65f5d-daad-4a9d-a0b0-d8549e0a0313", "type": "concept", "title": "Culture and biology"}, {"id": "d9bbaf57-563a-49b1-965c-52b4b602abfe", "type": "concept", "title": "Past and present"}, {"id": "febbc080-0692-44ee-9392-0d519395f9ee", "type": "concept", "title": "Local and global scales"}, {"id": "71b9c91d-e0cd-4488-9755-c41a90ea9174", "type": "concept", "title": "Comparison without ranking"}], "description": "The point is to see human life as interconnected rather than split into separate boxes."}, {"id": "3e39852e-1989-4323-af08-1e17378493d7", "type": "subtopic", "title": "Anthropological Questions", "children": [{"id": "abfa9a6d-cd8f-445e-9399-d13c5a539829", "type": "concept", "title": "What makes us human"}, {"id": "38583bef-ccbd-40c2-b62a-69054e3e3ecf", "type": "concept", "title": "How humans vary and adapt"}, {"id": "28fbb0a0-cf4d-4dea-a166-62d8ad98d6ce", "type": "concept", "title": "How societies organize meaning"}, {"id": "64395950-50a6-46e3-bc65-5c7611501141", "type": "concept", "title": "How power shapes lives"}], "description": "Students learn how anthropologists ask questions about what humans do, make, believe, inherit, and change."}]}, {"id": "93bfed0b-eb11-4db4-a843-54c9a9c80bee", "type": "topic", "title": "Culture, Society, Meaning, and the Anthropological Imagination", "description": "Culture is one of anthropology's central ideas, but it is also debated. Students learn to use the concept carefully without treating people as trapped in fixed traditions.", "children": [{"id": "92452ffa-10ea-4b9c-9a5e-e11d12269a8d", "type": "subtopic", "title": "Culture as Meaning and Practice", "children": [{"id": "8a895c9e-c3c2-4199-909b-3e9a16fd70ef", "type": "concept", "title": "Norms and values"}, {"id": "78d333f1-ef7c-4f62-8254-7f9a0fdec64c", "type": "concept", "title": "Symbols and classification"}, {"id": "1647d243-1e61-4ebf-8d9c-df286bba6b3d", "type": "concept", "title": "Practice and everyday life"}, {"id": "a66c3ec5-4487-4716-bffb-79e6ee5593af", "type": "concept", "title": "Culture as changing process"}], "description": "Students learn culture as lived habits, symbols, institutions, values, and ways of making sense."}, {"id": "69e9ca07-547f-40c2-b2ec-801744753772", "type": "subtopic", "title": "Ethnocentrism and Relativism", "children": [{"id": "1ecf51d2-9a4d-4d49-af00-f7d826d96738", "type": "concept", "title": "Ethnocentrism"}, {"id": "bad019bb-58e2-4f33-8b49-fcff76b1fc69", "type": "concept", "title": "Cultural relativism"}, {"id": "ba3a4dbc-97a5-4c51-a299-ebaaa2e65b76", "type": "concept", "title": "Methodological empathy"}, {"id": "266f87f2-0865-478a-9ca5-d5b7605e3bb7", "type": "concept", "title": "Ethical comparison"}], "description": "The gist is learning to understand difference before judging it."}, {"id": "13bb146b-c0f5-4da1-8f56-a39cf7f2c3d8", "type": "subtopic", "title": "Culture and Power", "children": [{"id": "f6bbfaa4-03b3-46ad-bb99-a35a1e9daa96", "type": "concept", "title": "Dominant and subcultural meanings"}, {"id": "4160e3d8-d70e-4d72-b107-d27b860ca5d9", "type": "concept", "title": "Tradition and invention"}, {"id": "ff18aa67-0953-4ded-9360-e299c0e3a977", "type": "concept", "title": "Identity and belonging"}, {"id": "5d544e6c-e6d9-43b2-ba4a-6b9f8de7ba75", "type": "concept", "title": "Culture, resistance, and change"}], "description": "Students learn that culture is never separate from inequality, history, and politics."}]}, {"id": "12647901-b766-4751-ab5f-9e07dbe18226", "type": "topic", "title": "Ethnography, Participant Observation, Fieldnotes, and Reflexivity", "description": "Ethnography is anthropology's signature way of learning. Students practice disciplined attention, listening, description, and reflection.", "children": [{"id": "a54d7a95-bc38-4128-8ddf-9bb5ce58bc3e", "type": "subtopic", "title": "Participant Observation", "children": [{"id": "388ffe61-0b3c-4495-8e10-74e8fd8ebabf", "type": "concept", "title": "Participation and observation"}, {"id": "2fb801e0-c9a1-40a0-b430-972c42838e76", "type": "concept", "title": "Rapport and trust"}, {"id": "0f1d037b-13cb-4b24-8464-875dce8bb23d", "type": "concept", "title": "Fieldsite and access"}, {"id": "82181b87-4c29-4571-ab91-54334b70a0cf", "type": "concept", "title": "Everyday life as evidence"}], "description": "Students learn why anthropologists often study with people in everyday settings."}, {"id": "ebc9351c-60e6-45b6-a60d-96618485ea0b", "type": "subtopic", "title": "Fieldnotes and Thick Description", "children": [{"id": "8a0f0f01-d8e9-4988-9695-53d2d9bc0731", "type": "concept", "title": "Jottings and expanded notes"}, {"id": "c154b1ab-44f0-4d18-b6eb-43efdae402cb", "type": "concept", "title": "Context and detail"}, {"id": "3fe92c36-96a0-4240-8143-9fd9b29fa3d4", "type": "concept", "title": "Emic and etic perspectives"}, {"id": "1d5948f3-f7e5-4b23-9612-81e652384a5a", "type": "concept", "title": "From description to analysis"}], "description": "The point is to turn observation into usable evidence."}, {"id": "be8c6dc1-e5a1-4a3f-b034-99bcb90cf8ad", "type": "subtopic", "title": "Reflexivity", "children": [{"id": "9e7d0c23-f60a-4573-9046-baaa250648bb", "type": "concept", "title": "Positionality"}, {"id": "65769041-c3cd-4f78-927e-13cbcc8abca0", "type": "concept", "title": "Power and access"}, {"id": "a16b59f5-8f8b-4441-bf01-1e5d9a31f847", "type": "concept", "title": "Bias and interpretation"}, {"id": "07b6dfdb-98ef-49d4-8ade-492482c8c4fb", "type": "concept", "title": "Reflexive writing"}], "description": "Students learn that researchers are part of the research encounter."}]}, {"id": "c7eb4f97-8ee2-4331-849a-aa4a58e0b8e9", "type": "topic", "title": "Human Evolution, Genetics, Primates, and Biological Variation", "description": "This unit introduces humans as biological and evolutionary beings. Students learn evolution and human variation without reducing culture to biology.", "children": [{"id": "d39f372d-6742-4b9d-8ead-0cc830239dda", "type": "subtopic", "title": "Evolution and Genetics", "children": [{"id": "f34818f9-edec-4395-a1f9-6e5d013752f6", "type": "concept", "title": "Natural selection"}, {"id": "dbdb630a-700d-4526-a5af-42fe5f0340f9", "type": "concept", "title": "Inheritance and population variation"}, {"id": "75f71977-06fb-4397-9aef-01faae462afe", "type": "concept", "title": "Adaptation"}, {"id": "c3ceccb3-927e-4af9-94cc-4b61960c402d", "type": "concept", "title": "Gene-culture interaction"}], "description": "Students learn the foundations needed to understand human origins and variation."}, {"id": "6c29c9b7-5908-4472-813f-fd5a4035c997", "type": "subtopic", "title": "Primates and Human Origins", "children": [{"id": "1c4f6a1a-cf30-4904-a34a-c709f56a5412", "type": "concept", "title": "Primate taxonomy and behavior"}, {"id": "6f0c4fdf-237a-476b-9343-1159af21c58f", "type": "concept", "title": "Bipedalism"}, {"id": "35ed7090-bcba-4bf1-a5ed-7773d0fcedec", "type": "concept", "title": "Homo evolution"}, {"id": "f7ef919a-eaf8-4ba6-a4a2-730cb10516e2", "type": "concept", "title": "Migration and dispersal"}], "description": "The gist is understanding humans in relation to other primates and fossil evidence."}, {"id": "c24942f6-af7a-43e8-b90f-b6f1a321a2e4", "type": "subtopic", "title": "Human Variation and Ethics", "children": [{"id": "260fbf0b-b505-46bb-b6f3-0589b844cb43", "type": "concept", "title": "Clinal variation"}, {"id": "38eed344-ec8e-4287-9025-f00bb043b0eb", "type": "concept", "title": "Skin color and adaptation"}, {"id": "c99439a6-9bc1-4b3f-8c3e-7bfe82583e93", "type": "concept", "title": "Race as social classification"}, {"id": "fc3ff5f6-1860-4fba-9439-ad940d56e5d1", "type": "concept", "title": "Human remains ethics"}], "description": "Students learn why biological variation is real but racial typology is scientifically and ethically flawed."}]}, {"id": "bfa9a2e7-d360-45b3-82f4-4e4b176b63ba", "type": "topic", "title": "Archaeology, Material Evidence, Dating, and the Human Past", "description": "Archaeology studies the human past through material evidence. Students learn how artifacts, sites, landscapes, and dates become interpretations of human life.", "children": [{"id": "0ab3474e-11ee-4b93-94e0-500f36a6e44c", "type": "subtopic", "title": "Archaeological Evidence", "children": [{"id": "f80d7e86-49c3-492f-90c8-7194ff2c0517", "type": "concept", "title": "Artifacts, ecofacts, and features"}, {"id": "18490a15-3648-4824-a85c-4e0869c38745", "type": "concept", "title": "Sites and landscapes"}, {"id": "f687110e-769e-4688-a7c6-35774df695a1", "type": "concept", "title": "Context and provenience"}, {"id": "81a0e128-cf92-4d84-897f-c5350b806fd2", "type": "concept", "title": "Taphonomy and preservation"}], "description": "Students learn what counts as evidence when people are not available to interview."}, {"id": "a6ad78e0-5abc-4fb7-a150-fea3869caaf8", "type": "subtopic", "title": "Field and Lab Methods", "children": [{"id": "9be31325-ce0f-4df1-88f1-81380136fd54", "type": "concept", "title": "Survey and excavation"}, {"id": "120a8f47-7809-4981-a6e7-e14aaed456cc", "type": "concept", "title": "Dating methods"}, {"id": "3231ec7e-91e3-4349-bbcd-8d3ddde61a5c", "type": "concept", "title": "Classification and typology"}, {"id": "0a9154fa-bce9-40d3-be58-0beb65dcc597", "type": "concept", "title": "Digital and laboratory analysis"}], "description": "The point is to understand how archaeological knowledge is produced."}, {"id": "668e9a28-3e05-4c56-bc24-7596f06003d0", "type": "subtopic", "title": "Heritage and Public Archaeology", "children": [{"id": "33df0d6a-d28e-4a22-9bb8-eff7238fba21", "type": "concept", "title": "Cultural heritage"}, {"id": "a5ef7251-fbc5-4e2d-a6d3-b094f40e0ac7", "type": "concept", "title": "Repatriation"}, {"id": "39c8df3c-8071-455a-ac83-c1e5cf5a1bb0", "type": "concept", "title": "Looting and preservation"}, {"id": "31283e9d-151d-4f22-9083-d26df2d7f76a", "type": "concept", "title": "Public interpretation"}], "description": "Students learn that archaeology involves living communities, law, memory, and stewardship."}]}, {"id": "5e01860f-64a9-41a8-8b09-4d9392655f0a", "type": "topic", "title": "Language, Communication, Identity, and Linguistic Diversity", "description": "Language is central to human social life. Students learn that speaking, signing, writing, silence, and translation all carry identity and power.", "children": [{"id": "dd0599ec-35d8-4fa8-aa4e-236f507466e3", "type": "subtopic", "title": "Language as Social Action", "children": [{"id": "5005baa7-ccc7-4a12-bf17-96dd1d594f83", "type": "concept", "title": "Speech communities"}, {"id": "646d5f97-f117-4822-9c49-4e8c035f0e8a", "type": "concept", "title": "Registers"}, {"id": "b8fcbe06-e0db-425b-8f12-7ccf886164ec", "type": "concept", "title": "Performance"}, {"id": "3cfa627f-2659-45f0-aa45-057369442774", "type": "concept", "title": "Interaction and meaning"}], "description": "Students learn how language does things in relationships and institutions."}, {"id": "bf99d83b-7d5a-453c-97c8-4a368f0c9cd6", "type": "subtopic", "title": "Language Ideology", "children": [{"id": "0c6159d2-8603-49b3-9783-aa138e4ce069", "type": "concept", "title": "Standard language ideology"}, {"id": "fa8a95b6-10c1-47ae-8f0d-b8162e52cd59", "type": "concept", "title": "Accent and discrimination"}, {"id": "7a9168b7-f11c-4ec6-a956-d68d79f36813", "type": "concept", "title": "Code-switching"}, {"id": "9c7c9dc7-529f-4f2b-8069-a750a701bdb5", "type": "concept", "title": "Language, race, gender, and class"}], "description": "The gist is understanding how beliefs about language create hierarchy."}, {"id": "6fc128db-0e83-4653-b2d8-7c120755467a", "type": "subtopic", "title": "Language Diversity and Change", "children": [{"id": "d4219db6-37fc-4253-81e8-7e4e236aa936", "type": "concept", "title": "Multilingualism"}, {"id": "4ef9b44b-d336-4c2e-93f4-73163e1b51bc", "type": "concept", "title": "Language contact"}, {"id": "b5302a77-779f-4422-bac0-bd2a1af9deb4", "type": "concept", "title": "Endangerment"}, {"id": "cd6f2a1e-2cf1-4fa0-ac2b-ad20f0058318", "type": "concept", "title": "Revitalization"}], "description": "Students learn why language diversity matters and how languages change or become endangered."}]}, {"id": "7826eeb7-81da-4b95-9acc-5c0490cdcc08", "type": "topic", "title": "Kinship, Relatedness, Households, Exchange, and Social Organization", "description": "Kinship and exchange show how people create social ties, obligations, and belonging. Students learn that family and economy are culturally organized.", "children": [{"id": "d0546803-7ea5-4617-9e15-2f563a164235", "type": "subtopic", "title": "Kinship and Relatedness", "children": [{"id": "bbf720e4-c094-469c-a422-fba80596fc02", "type": "concept", "title": "Descent and lineage"}, {"id": "1fa059e8-b505-4023-a0bf-e1914b92236a", "type": "concept", "title": "Marriage and alliance"}, {"id": "c5c103b8-ce4b-4e8d-92b8-8a3086258a25", "type": "concept", "title": "Adoption and fostering"}, {"id": "efbb6126-1e68-47ec-ba5a-852dd293030f", "type": "concept", "title": "Queer and chosen kinship"}], "description": "Students learn that relatedness is made through biology, law, ritual, care, and everyday practice."}, {"id": "e7fbbc1a-ec14-42c2-a947-11da6dddbfe3", "type": "subtopic", "title": "Households and Social Organization", "children": [{"id": "27969dfe-742b-49ba-9313-7f59edb732fd", "type": "concept", "title": "Households"}, {"id": "62c3b62b-1f76-4aec-be80-2c47e1db2df1", "type": "concept", "title": "Residence patterns"}, {"id": "32bb7193-a0f8-4761-8166-2412c4ac0cb5", "type": "concept", "title": "Age and generation"}, {"id": "db148c6f-fd3f-4fac-9caf-0ad770e8fc80", "type": "concept", "title": "Community organization"}], "description": "The point is to analyze how groups coordinate care, work, inheritance, and residence."}, {"id": "c7530a72-1201-4aca-a83d-29cba4cf0fc4", "type": "subtopic", "title": "Exchange and Reciprocity", "children": [{"id": "9f4ba719-877d-47c6-a09c-bf8dda062c13", "type": "concept", "title": "Reciprocity"}, {"id": "d5777924-a997-4287-986a-1be4b2b95200", "type": "concept", "title": "Redistribution"}, {"id": "90de0511-4f4d-4dae-b5c4-88b6a01d0b4e", "type": "concept", "title": "Market exchange"}, {"id": "9da68a60-ddad-4cc1-9902-2bb7a1090f3e", "type": "concept", "title": "Obligation and social debt"}], "description": "Students learn how gifts and obligations build relationships."}]}, {"id": "3790e368-f355-4033-8689-d11680fd9ae3", "type": "topic", "title": "Religion, Ritual, Symbolism, Myth, and Worldview", "description": "Ritual and belief help students understand how humans create meaning, order, healing, and community.", "children": [{"id": "9181242c-c194-4668-ae71-e97a4bc16ac5", "type": "subtopic", "title": "Ritual", "children": [{"id": "ef74a603-c56e-491f-b2d7-a4b49e73cdc8", "type": "concept", "title": "Rites of passage"}, {"id": "ce8d0e84-806a-4907-877a-29c94fd46eb7", "type": "concept", "title": "Sacred and profane"}, {"id": "537dd174-f7de-4265-9382-e68f6e2cb129", "type": "concept", "title": "Performance"}, {"id": "17f38dd7-8f2b-4175-807d-c077e03aa429", "type": "concept", "title": "Collective identity"}], "description": "Students learn ritual as repeated symbolic action that marks transitions and produces belonging."}, {"id": "1ed0d664-e834-41d6-94d2-e904b5465766", "type": "subtopic", "title": "Religion and Worldview", "children": [{"id": "2edd383e-b8fd-4909-853d-a2c4b3a4b0c7", "type": "concept", "title": "Myth and cosmology"}, {"id": "87dae388-d068-4fe2-a46f-5a79ad418447", "type": "concept", "title": "Spirits and ancestors"}, {"id": "26933f0e-65f3-4c5f-868e-5934593ec5fe", "type": "concept", "title": "Magic and witchcraft"}, {"id": "69eaa693-9ad7-4d3a-ad95-d51f942f999d", "type": "concept", "title": "Secularism"}], "description": "The gist is to interpret belief systems as lived social worlds."}, {"id": "b55e74cc-b1e3-4940-bfa1-67f20e3d6bc0", "type": "subtopic", "title": "Symbolism and Meaning", "children": [{"id": "5e533131-4ab8-40ad-81cb-b73faaacc6c1", "type": "concept", "title": "Interpretive anthropology"}, {"id": "385a26ca-479f-405d-9106-de2bc1b7072b", "type": "concept", "title": "Metaphor and classification"}, {"id": "a8a46c19-8a88-4581-8676-83b4fdcad232", "type": "concept", "title": "Material religion"}, {"id": "ecb2c53c-c8d6-4c70-8473-732b5ba4155c", "type": "concept", "title": "Ritual and power"}], "description": "Students learn to read symbols in context rather than as universal codes."}]}, {"id": "437419ae-50bc-42b5-a548-c71ce509caef", "type": "topic", "title": "Gender, Sexuality, Personhood, Bodies, and the Life Course", "description": "Gender, sexuality, personhood, and bodies vary across societies and histories. Students learn to analyze identity as embodied and social.", "children": [{"id": "722cfbbc-fbc9-4c9e-b251-154c14b3b41f", "type": "subtopic", "title": "Gender and Sexuality", "children": [{"id": "d2163f2d-8448-4267-8626-d868d01a6883", "type": "concept", "title": "Sex and gender"}, {"id": "bfcfe4b7-1e43-4342-a172-c3451ccb0b86", "type": "concept", "title": "Gender roles"}, {"id": "6665e47c-d76e-4840-915d-94f1affe0e76", "type": "concept", "title": "Sexual norms"}, {"id": "18f00eeb-48fe-41d4-a5bd-4f273b321e8c", "type": "concept", "title": "Gender diversity"}], "description": "Students learn how gender and sexuality are socially organized and contested."}, {"id": "54b39455-88a0-4d7a-ab4d-0a90f5c119da", "type": "subtopic", "title": "Personhood and Identity", "children": [{"id": "9e7a5c9b-f52f-4b52-8c84-b791e001e0c0", "type": "concept", "title": "Individual and relational selves"}, {"id": "7dc48cf5-38cc-4fd6-b07e-19853ce133f2", "type": "concept", "title": "Name, status, and recognition"}, {"id": "16641f3b-19da-4000-b965-c29e76649d43", "type": "concept", "title": "Personhood and rights"}, {"id": "d66d76eb-716a-463f-9212-8772ebdb955b", "type": "concept", "title": "Identity and belonging"}], "description": "The point is to see that ideas of the self are cultural and political."}, {"id": "ed698e84-e320-48cd-8bfb-17b76cacf9eb", "type": "subtopic", "title": "Bodies and Life Course", "children": [{"id": "9440f613-c46a-4dfd-b4f8-15ef5578da19", "type": "concept", "title": "Birth and childhood"}, {"id": "4ef7e49d-ee94-4f32-881f-edcd5e930c5e", "type": "concept", "title": "Coming of age"}, {"id": "0c1271da-cbc8-4aa7-8cc6-47a4eefcc165", "type": "concept", "title": "Disability and embodiment"}, {"id": "1299e863-ac97-4aed-ade4-6891ef415190", "type": "concept", "title": "Aging and death"}], "description": "Students learn how bodies are shaped through culture, inequality, ritual, and time."}]}, {"id": "d2dbbfe4-a19f-46ec-b7c2-f1d74ae1755a", "type": "topic", "title": "Race, Ethnicity, Colonialism, Indigeneity, and Power", "description": "This unit connects anthropology to colonial histories and contemporary struggles over identity, land, knowledge, and power.", "children": [{"id": "f2bfa576-eec6-497f-89b6-4eecc3930591", "type": "subtopic", "title": "Race and Ethnicity", "children": [{"id": "281daaa5-56d7-4722-bc71-977a97c27937", "type": "concept", "title": "Race as social construction"}, {"id": "0c51e3d7-d3ed-4d09-8070-84e5b6acf4e1", "type": "concept", "title": "Ethnic boundaries"}, {"id": "a53fca48-ba2a-4e45-af37-76730073ae28", "type": "concept", "title": "Racism and classification"}, {"id": "2111d67a-c9e6-4c94-9768-d681f49519f2", "type": "concept", "title": "Diaspora and identity"}], "description": "Students learn race and ethnicity as historical classifications with real social consequences."}, {"id": "485ccd20-da4b-4926-b9ad-d2dc3f362655", "type": "subtopic", "title": "Colonialism and Indigeneity", "children": [{"id": "a973a9fb-2d7a-487d-917e-ab086b1d3ad5", "type": "concept", "title": "Colonial knowledge"}, {"id": "6c69c838-a0af-4899-9833-cdefcdbc4a7e", "type": "concept", "title": "Settler colonialism"}, {"id": "0bf44077-5c58-4134-9c2b-1f38de550525", "type": "concept", "title": "Indigenous sovereignty"}, {"id": "b1d16630-f0a0-4457-9a97-0f557ec046b8", "type": "concept", "title": "Decolonizing anthropology"}], "description": "The gist is understanding how anthropology was shaped by empire and how Indigenous communities challenge colonial power."}, {"id": "2d55c89a-b32c-4240-b3ea-d940a3af0158", "type": "subtopic", "title": "Nationalism and Heritage", "children": [{"id": "01f6c189-39d2-4a6f-a1ce-1b250d24df9a", "type": "concept", "title": "Imagined communities"}, {"id": "7ebccb46-0f70-4e47-9453-152f5f859a31", "type": "concept", "title": "Museums and collecting"}, {"id": "4c18d329-8058-4b67-9a4e-f1bf12703270", "type": "concept", "title": "Repatriation"}, {"id": "7f2df34c-ec36-4345-ada0-ff20df084e5f", "type": "concept", "title": "Cultural property"}], "description": "Students learn how nations, museums, and heritage institutions organize belonging and memory."}]}, {"id": "678aecc4-cb04-49c1-87cf-312fe6da74e0", "type": "topic", "title": "Economy, Subsistence, Labor, Gifts, Markets, and Inequality", "description": "Anthropology treats economic life as social and moral life. Students compare how people produce, exchange, value, and survive.", "children": [{"id": "092c8ee8-5209-4ee3-a89d-37f37290abf9", "type": "subtopic", "title": "Subsistence and Livelihood", "children": [{"id": "2c79ab5e-ea90-4bc7-b602-1034b1476d84", "type": "concept", "title": "Foraging"}, {"id": "c6fc2bf4-8bc6-4fd5-9461-a948b6d8ec0c", "type": "concept", "title": "Pastoralism and agriculture"}, {"id": "95670ffa-7201-4cf7-a3a8-39e8510c256c", "type": "concept", "title": "Industrial labor"}, {"id": "dfa35e39-19a6-4165-9e2c-86d664813096", "type": "concept", "title": "Informal economies"}], "description": "Students compare ways people obtain food, resources, and security."}, {"id": "f133f2d6-3763-4587-a777-1385133381c4", "type": "subtopic", "title": "Gifts, Markets, and Value", "children": [{"id": "0896bfd2-08a0-4744-9761-cd29ac3dc5c7", "type": "concept", "title": "The gift"}, {"id": "fb2fe5e8-5b27-4b56-b869-034597914159", "type": "concept", "title": "Commodities"}, {"id": "a38c8dc9-571a-4e69-a770-2ef7b8ae402b", "type": "concept", "title": "Debt"}, {"id": "c74d1cbd-f54b-40a5-ab71-0f29d9abe7b8", "type": "concept", "title": "Moral economies"}], "description": "The point is to see exchange as relationship, obligation, and meaning."}, {"id": "01099996-0a1e-4960-ba44-fe0335145183", "type": "subtopic", "title": "Inequality and Political Economy", "children": [{"id": "ecde2d7c-0bab-4e6c-9a79-60cfb09a79fc", "type": "concept", "title": "Class and labor"}, {"id": "c10074f6-ec7c-4368-b503-0130bea988ca", "type": "concept", "title": "Development and aid"}, {"id": "504ce5a6-8c29-4c2a-8652-28128f09a3d3", "type": "concept", "title": "Global supply chains"}, {"id": "996b509d-ea9d-4ab8-9eac-7585b49e3273", "type": "concept", "title": "Neoliberalism"}], "description": "Students learn how capitalism, development, and dispossession shape everyday life."}]}, {"id": "32addead-70da-4882-9080-fe96bedfacbb", "type": "topic", "title": "Political Authority, Law, Conflict, Violence, and the State", "description": "Political anthropology studies authority and conflict in both state and non-state contexts. Students learn how power is organized and resisted.", "children": [{"id": "b0a6556a-321b-4868-9fb6-b9db3e27055c", "type": "subtopic", "title": "Authority and Governance", "children": [{"id": "7c6b9853-7a1e-46da-b66f-fa80ea3036ef", "type": "concept", "title": "Bands, tribes, chiefdoms, and states"}, {"id": "ff0c6936-70ed-48ef-a387-2310cf40c37f", "type": "concept", "title": "Leadership and legitimacy"}, {"id": "778f52a2-f0ba-447b-9977-185a79d40520", "type": "concept", "title": "Customary authority"}, {"id": "24ff3b72-e8a1-4c51-a69b-449440feb2b5", "type": "concept", "title": "Bureaucracy"}], "description": "Students compare ways societies organize leadership and decision-making."}, {"id": "5609e10c-cc32-495c-850b-efc85fa7085d", "type": "subtopic", "title": "Law and Citizenship", "children": [{"id": "59153826-4958-4e3a-b096-463cbc5fadc1", "type": "concept", "title": "Legal pluralism"}, {"id": "72b3152d-9930-41d9-a095-34cb9291c5ce", "type": "concept", "title": "Citizenship"}, {"id": "ba69cf4f-a23b-4357-8733-02c1771e4534", "type": "concept", "title": "Sovereignty"}, {"id": "f8c76427-fd64-45a1-84be-53ed7bbc5409", "type": "concept", "title": "Borders and documents"}], "description": "The gist is understanding rules, rights, and belonging as culturally and politically made."}, {"id": "4437928f-9e95-4263-947d-769577a853af", "type": "subtopic", "title": "Conflict and Violence", "children": [{"id": "1f7f103a-4480-4462-a633-f8b027018574", "type": "concept", "title": "War and security"}, {"id": "99e7d3b3-37ed-4121-83d5-684c5885ce8f", "type": "concept", "title": "Structural violence"}, {"id": "f9478563-c428-4e1c-b6dc-285e7cefdc1b", "type": "concept", "title": "Everyday resistance"}, {"id": "a56309f1-595f-4348-ab8f-6d4c7016ccec", "type": "concept", "title": "Social movements"}], "description": "Students learn to analyze violence as social, structural, symbolic, and historical."}]}, {"id": "6c6b4379-d1e8-4c07-812a-e5051f15c51a", "type": "topic", "title": "Globalization, Migration, Diaspora, Development, and Transnational Life", "description": "Culture moves. Students study migration, diaspora, global media, tourism, aid, and transnational life as uneven and power-laden processes.", "children": [{"id": "859b7bb3-d512-485c-ac30-ced88c41b9f0", "type": "subtopic", "title": "Globalization", "children": [{"id": "13111188-3216-475b-8d78-3945cb62d659", "type": "concept", "title": "Cultural flows"}, {"id": "8bd72cf7-f2a7-4731-ae8c-b0ba372d8912", "type": "concept", "title": "Global capitalism"}, {"id": "6bcdd10a-6037-4018-95ba-c1674768bba0", "type": "concept", "title": "Tourism"}, {"id": "bf1d7a5c-5dd0-4125-afa6-eb9aec801292", "type": "concept", "title": "Media and consumption"}], "description": "Students learn how people, goods, images, money, and ideas circulate unevenly."}, {"id": "b53d5d07-9f77-45ae-aa54-f16187a6d0a1", "type": "subtopic", "title": "Migration and Diaspora", "children": [{"id": "b67d8643-73db-43ee-9d0f-1a384146852b", "type": "concept", "title": "Refugees and displacement"}, {"id": "710b2512-6ec9-4369-bccd-238550ef309f", "type": "concept", "title": "Labor migration"}, {"id": "0c74aef6-e4f8-4953-b99c-1142117b9b05", "type": "concept", "title": "Transnational families"}, {"id": "7956e090-c113-4fed-8305-944e3a0e0f15", "type": "concept", "title": "Diaspora and home"}], "description": "The point is to examine movement as emotional, economic, legal, and cultural."}, {"id": "2cf01fc3-fc8a-48ce-8e1b-2cf7bc4f63e4", "type": "subtopic", "title": "Development and Humanitarianism", "children": [{"id": "1b15fbd1-bf2f-4671-8d26-036b7860c66a", "type": "concept", "title": "NGOs"}, {"id": "2d15a8aa-bd54-47f8-8373-f713f42f86e4", "type": "concept", "title": "Participation"}, {"id": "a27a62e5-c465-4dfd-9b65-cf706d33e08a", "type": "concept", "title": "Development discourse"}, {"id": "3625d823-d0be-4ce0-bced-74ee251d9255", "type": "concept", "title": "Aid and accountability"}], "description": "Students learn to question expertise, aid, intervention, and unintended consequences."}]}, {"id": "3b4d5598-03bc-46eb-bf8a-160db6dd55df", "type": "topic", "title": "Medical, Environmental, Digital, and Public Anthropology", "description": "This unit shows how anthropology addresses urgent contemporary issues in health, environment, media, and public life.", "children": [{"id": "dc79b156-cd44-48ab-a944-c87935a4e57f", "type": "subtopic", "title": "Medical Anthropology", "children": [{"id": "621cbbfe-5555-4415-becd-f0ef2ec05eac", "type": "concept", "title": "Illness experience"}, {"id": "b2b0168f-49e2-43ee-9f2b-20e46ac2a9a3", "type": "concept", "title": "Biomedicine as culture"}, {"id": "eaefbf59-4faa-4d78-9676-0ccc8a0d588e", "type": "concept", "title": "Healing systems"}, {"id": "23789294-76b1-46d2-b47f-7cf8b7752316", "type": "concept", "title": "Structural violence"}], "description": "Students learn that health is biological, cultural, political, and economic."}, {"id": "5274e37b-f5a1-4f78-a099-136b83c6bec5", "type": "subtopic", "title": "Environmental and Multispecies Anthropology", "children": [{"id": "402b0eaa-6ee4-4848-b155-e658d5c24b84", "type": "concept", "title": "Political ecology"}, {"id": "fe636e83-f53e-4be2-a8f1-c7289947603b", "type": "concept", "title": "Climate vulnerability"}, {"id": "432b351c-3d59-475b-9145-4e3820811be6", "type": "concept", "title": "Food systems"}, {"id": "896397c9-1b02-4963-9aa2-a357feacaf65", "type": "concept", "title": "Animals, plants, and microbes"}], "description": "The gist is understanding humans as ecological beings entangled with other species and infrastructures."}, {"id": "59401e98-3262-45f4-870a-f9c04a4f6ab3", "type": "subtopic", "title": "Digital and Public Anthropology", "children": [{"id": "63f5ad34-eec5-4685-b2ab-ff5d887d7297", "type": "concept", "title": "Digital ethnography"}, {"id": "1d7a3dde-509f-4ecd-b141-9d1e8b98743b", "type": "concept", "title": "Platforms and algorithms"}, {"id": "7eca6214-451d-407b-8c13-05007770e89c", "type": "concept", "title": "Public writing"}, {"id": "fd171fcf-72f6-4584-8d7b-e869703b65b1", "type": "concept", "title": "Research translation"}], "description": "Students learn to study online life and communicate anthropology beyond the classroom."}]}, {"id": "fa704f80-b919-44d3-81d1-872ae5f60c71", "type": "topic", "title": "Applied Anthropology, Ethics, Careers, and Final Anthropological Synthesis", "description": "The final unit turns anthropology into practice. Students synthesize concepts, ethics, methods, and career pathways through applied work.", "children": [{"id": "7695fb97-cb52-4b7c-8731-356e812e108f", "type": "subtopic", "title": "Applied Anthropology", "children": [{"id": "7a3aedd0-045d-4612-83e1-5f8b87063a9a", "type": "concept", "title": "Needs assessment"}, {"id": "9fc6d7ae-68e8-418e-a57d-6e7107c99444", "type": "concept", "title": "Program evaluation"}, {"id": "2cb7bba9-9032-40a1-bf3d-f170e91b3f8e", "type": "concept", "title": "Design anthropology"}, {"id": "5de017af-ce52-4fd5-931e-0aedc68f1179", "type": "concept", "title": "Cultural resource management"}], "description": "Students learn how anthropologists work in health, design, policy, museums, education, environment, and business."}, {"id": "2a883d32-73dd-4c04-8cd4-4d910effdee5", "type": "subtopic", "title": "Ethics and Professional Responsibility", "children": [{"id": "89b0ce75-2674-49f5-8a4b-167568367215", "type": "concept", "title": "AAA ethics"}, {"id": "56889c12-292f-412f-bd7a-4fa8b5e12934", "type": "concept", "title": "Consent and collaboration"}, {"id": "0b9129ba-26d3-4beb-ad4f-e9e3a913fcfe", "type": "concept", "title": "Data sovereignty"}, {"id": "0a8b05ee-cbbb-4e22-8882-954f49187a31", "type": "concept", "title": "Responsible return of findings"}], "description": "The point is to connect methods to accountability."}, {"id": "6e6812d9-77a2-48f3-9a7d-134bcf33b6d3", "type": "subtopic", "title": "Final Anthropological Synthesis", "children": [{"id": "a1ed424c-5cf2-4b94-9a35-4b293316866a", "type": "concept", "title": "Portfolio or final brief"}, {"id": "6b2f7037-5afa-4627-b5db-f7982fc34e36", "type": "concept", "title": "Case comparison"}, {"id": "0034f3a9-9bcf-4c3b-9a76-d56b3d169e3f", "type": "concept", "title": "Public presentation"}, {"id": "e6a1c82a-2fcc-4552-bd55-5cd40af07cbb", "type": "concept", "title": "Career and civic transfer"}], "description": "Students pull together the four fields and communicate what anthropology helps them see."}]}], "dbBacked": true}$inanjson$::jsonb,
