insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e8d86dbb-a0fa-4ffb-9a06-94d5586de5ca', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', null, 'topic'::public.curated_course_node_type, 'Anthropology as a Holistic, Comparative Study of Humanity', 'This opening unit gives students the map of the field. They learn that anthropology asks big questions about humanity by combining culture, biology, language, material evidence, history, and fieldwork.', 0),
  ('883b14fa-755c-496f-ae71-60094072b38a', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'e8d86dbb-a0fa-4ffb-9a06-94d5586de5ca', 'subtopic'::public.curated_course_node_type, 'The Four-Field Frame', 'Students learn how cultural, biological, archaeological, and linguistic anthropology work together.', 0),
  ('2331408e-3347-4b39-a2fc-d76366b4a359', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '883b14fa-755c-496f-ae71-60094072b38a', 'concept'::public.curated_course_node_type, 'Cultural anthropology', null, 0),
  ('7ff13121-3a94-429d-af12-b083e3858080', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '883b14fa-755c-496f-ae71-60094072b38a', 'concept'::public.curated_course_node_type, 'Biological or physical anthropology', null, 1),
  ('5b161910-ce6d-46a6-b0b0-a727e3667d4c', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '883b14fa-755c-496f-ae71-60094072b38a', 'concept'::public.curated_course_node_type, 'Archaeology', null, 2),
  ('ee323cba-ba37-4961-8a01-cdb14ad9d09f', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '883b14fa-755c-496f-ae71-60094072b38a', 'concept'::public.curated_course_node_type, 'Linguistic anthropology', null, 3),
  ('ee368664-5283-4a48-8549-f5ee2ceca4eb', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'e8d86dbb-a0fa-4ffb-9a06-94d5586de5ca', 'subtopic'::public.curated_course_node_type, 'Holism and Comparison', 'The point is to see human life as interconnected rather than split into separate boxes.', 1),
  ('2dc65f5d-daad-4a9d-a0b0-d8549e0a0313', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'ee368664-5283-4a48-8549-f5ee2ceca4eb', 'concept'::public.curated_course_node_type, 'Culture and biology', null, 0),
  ('d9bbaf57-563a-49b1-965c-52b4b602abfe', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'ee368664-5283-4a48-8549-f5ee2ceca4eb', 'concept'::public.curated_course_node_type, 'Past and present', null, 1),
  ('febbc080-0692-44ee-9392-0d519395f9ee', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'ee368664-5283-4a48-8549-f5ee2ceca4eb', 'concept'::public.curated_course_node_type, 'Local and global scales', null, 2),
  ('71b9c91d-e0cd-4488-9755-c41a90ea9174', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'ee368664-5283-4a48-8549-f5ee2ceca4eb', 'concept'::public.curated_course_node_type, 'Comparison without ranking', null, 3),
  ('3e39852e-1989-4323-af08-1e17378493d7', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'e8d86dbb-a0fa-4ffb-9a06-94d5586de5ca', 'subtopic'::public.curated_course_node_type, 'Anthropological Questions', 'Students learn how anthropologists ask questions about what humans do, make, believe, inherit, and change.', 2),
  ('abfa9a6d-cd8f-445e-9399-d13c5a539829', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '3e39852e-1989-4323-af08-1e17378493d7', 'concept'::public.curated_course_node_type, 'What makes us human', null, 0),
  ('38583bef-ccbd-40c2-b62a-69054e3e3ecf', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '3e39852e-1989-4323-af08-1e17378493d7', 'concept'::public.curated_course_node_type, 'How humans vary and adapt', null, 1),
  ('28fbb0a0-cf4d-4dea-a166-62d8ad98d6ce', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '3e39852e-1989-4323-af08-1e17378493d7', 'concept'::public.curated_course_node_type, 'How societies organize meaning', null, 2),
  ('64395950-50a6-46e3-bc65-5c7611501141', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '3e39852e-1989-4323-af08-1e17378493d7', 'concept'::public.curated_course_node_type, 'How power shapes lives', null, 3),
  ('93bfed0b-eb11-4db4-a843-54c9a9c80bee', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', null, 'topic'::public.curated_course_node_type, 'Culture, Society, Meaning, and the Anthropological Imagination', 'Culture is one of anthropology''s central ideas, but it is also debated. Students learn to use the concept carefully without treating people as trapped in fixed traditions.', 1),
  ('92452ffa-10ea-4b9c-9a5e-e11d12269a8d', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '93bfed0b-eb11-4db4-a843-54c9a9c80bee', 'subtopic'::public.curated_course_node_type, 'Culture as Meaning and Practice', 'Students learn culture as lived habits, symbols, institutions, values, and ways of making sense.', 0),
  ('8a895c9e-c3c2-4199-909b-3e9a16fd70ef', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '92452ffa-10ea-4b9c-9a5e-e11d12269a8d', 'concept'::public.curated_course_node_type, 'Norms and values', null, 0),
  ('78d333f1-ef7c-4f62-8254-7f9a0fdec64c', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '92452ffa-10ea-4b9c-9a5e-e11d12269a8d', 'concept'::public.curated_course_node_type, 'Symbols and classification', null, 1),
  ('1647d243-1e61-4ebf-8d9c-df286bba6b3d', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '92452ffa-10ea-4b9c-9a5e-e11d12269a8d', 'concept'::public.curated_course_node_type, 'Practice and everyday life', null, 2),
  ('a66c3ec5-4487-4716-bffb-79e6ee5593af', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '92452ffa-10ea-4b9c-9a5e-e11d12269a8d', 'concept'::public.curated_course_node_type, 'Culture as changing process', null, 3),
  ('69e9ca07-547f-40c2-b2ec-801744753772', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '93bfed0b-eb11-4db4-a843-54c9a9c80bee', 'subtopic'::public.curated_course_node_type, 'Ethnocentrism and Relativism', 'The gist is learning to understand difference before judging it.', 1),
  ('1ecf51d2-9a4d-4d49-af00-f7d826d96738', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '69e9ca07-547f-40c2-b2ec-801744753772', 'concept'::public.curated_course_node_type, 'Ethnocentrism', null, 0),
  ('bad019bb-58e2-4f33-8b49-fcff76b1fc69', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '69e9ca07-547f-40c2-b2ec-801744753772', 'concept'::public.curated_course_node_type, 'Cultural relativism', null, 1),
  ('ba3a4dbc-97a5-4c51-a299-ebaaa2e65b76', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '69e9ca07-547f-40c2-b2ec-801744753772', 'concept'::public.curated_course_node_type, 'Methodological empathy', null, 2),
  ('266f87f2-0865-478a-9ca5-d5b7605e3bb7', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '69e9ca07-547f-40c2-b2ec-801744753772', 'concept'::public.curated_course_node_type, 'Ethical comparison', null, 3),
  ('13bb146b-c0f5-4da1-8f56-a39cf7f2c3d8', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '93bfed0b-eb11-4db4-a843-54c9a9c80bee', 'subtopic'::public.curated_course_node_type, 'Culture and Power', 'Students learn that culture is never separate from inequality, history, and politics.', 2),
  ('f6bbfaa4-03b3-46ad-bb99-a35a1e9daa96', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '13bb146b-c0f5-4da1-8f56-a39cf7f2c3d8', 'concept'::public.curated_course_node_type, 'Dominant and subcultural meanings', null, 0),
  ('4160e3d8-d70e-4d72-b107-d27b860ca5d9', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '13bb146b-c0f5-4da1-8f56-a39cf7f2c3d8', 'concept'::public.curated_course_node_type, 'Tradition and invention', null, 1),
  ('ff18aa67-0953-4ded-9360-e299c0e3a977', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '13bb146b-c0f5-4da1-8f56-a39cf7f2c3d8', 'concept'::public.curated_course_node_type, 'Identity and belonging', null, 2),
  ('5d544e6c-e6d9-43b2-ba4a-6b9f8de7ba75', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '13bb146b-c0f5-4da1-8f56-a39cf7f2c3d8', 'concept'::public.curated_course_node_type, 'Culture, resistance, and change', null, 3),
  ('12647901-b766-4751-ab5f-9e07dbe18226', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', null, 'topic'::public.curated_course_node_type, 'Ethnography, Participant Observation, Fieldnotes, and Reflexivity', 'Ethnography is anthropology''s signature way of learning. Students practice disciplined attention, listening, description, and reflection.', 2),
  ('a54d7a95-bc38-4128-8ddf-9bb5ce58bc3e', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '12647901-b766-4751-ab5f-9e07dbe18226', 'subtopic'::public.curated_course_node_type, 'Participant Observation', 'Students learn why anthropologists often study with people in everyday settings.', 0),
  ('388ffe61-0b3c-4495-8e10-74e8fd8ebabf', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'a54d7a95-bc38-4128-8ddf-9bb5ce58bc3e', 'concept'::public.curated_course_node_type, 'Participation and observation', null, 0),
  ('2fb801e0-c9a1-40a0-b430-972c42838e76', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'a54d7a95-bc38-4128-8ddf-9bb5ce58bc3e', 'concept'::public.curated_course_node_type, 'Rapport and trust', null, 1),
  ('0f1d037b-13cb-4b24-8464-875dce8bb23d', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'a54d7a95-bc38-4128-8ddf-9bb5ce58bc3e', 'concept'::public.curated_course_node_type, 'Fieldsite and access', null, 2),
  ('82181b87-4c29-4571-ab91-54334b70a0cf', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'a54d7a95-bc38-4128-8ddf-9bb5ce58bc3e', 'concept'::public.curated_course_node_type, 'Everyday life as evidence', null, 3),
  ('ebc9351c-60e6-45b6-a60d-96618485ea0b', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '12647901-b766-4751-ab5f-9e07dbe18226', 'subtopic'::public.curated_course_node_type, 'Fieldnotes and Thick Description', 'The point is to turn observation into usable evidence.', 1),
  ('8a0f0f01-d8e9-4988-9695-53d2d9bc0731', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'ebc9351c-60e6-45b6-a60d-96618485ea0b', 'concept'::public.curated_course_node_type, 'Jottings and expanded notes', null, 0);
