  ('c154b1ab-44f0-4d18-b6eb-43efdae402cb', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'ebc9351c-60e6-45b6-a60d-96618485ea0b', 'concept'::public.curated_course_node_type, 'Context and detail', null, 1),
