  ('be8c6dc1-e5a1-4a3f-b034-99bcb90cf8ad', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '12647901-b766-4751-ab5f-9e07dbe18226', 'subtopic'::public.curated_course_node_type, 'Reflexivity', 'Students learn that researchers are part of the research encounter.', 2),
  ('9e7d0c23-f60a-4573-9046-baaa250648bb', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'be8c6dc1-e5a1-4a3f-b034-99bcb90cf8ad', 'concept'::public.curated_course_node_type, 'Positionality', null, 0),
  ('65769041-c3cd-4f78-927e-13cbcc8abca0', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'be8c6dc1-e5a1-4a3f-b034-99bcb90cf8ad', 'concept'::public.curated_course_node_type, 'Power and access', null, 1),
  ('a16b59f5-8f8b-4441-bf01-1e5d9a31f847', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'be8c6dc1-e5a1-4a3f-b034-99bcb90cf8ad', 'concept'::public.curated_course_node_type, 'Bias and interpretation', null, 2),
  ('07b6dfdb-98ef-49d4-8ade-492482c8c4fb', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'be8c6dc1-e5a1-4a3f-b034-99bcb90cf8ad', 'concept'::public.curated_course_node_type, 'Reflexive writing', null, 3),
  ('c7eb4f97-8ee2-4331-849a-aa4a58e0b8e9', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', null, 'topic'::public.curated_course_node_type, 'Human Evolution, Genetics, Primates, and Biological Variation', 'This unit introduces humans as biological and evolutionary beings. Students learn evolution and human variation without reducing culture to biology.', 3),
  ('d39f372d-6742-4b9d-8ead-0cc830239dda', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'c7eb4f97-8ee2-4331-849a-aa4a58e0b8e9', 'subtopic'::public.curated_course_node_type, 'Evolution and Genetics', 'Students learn the foundations needed to understand human origins and variation.', 0),
  ('f34818f9-edec-4395-a1f9-6e5d013752f6', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'd39f372d-6742-4b9d-8ead-0cc830239dda', 'concept'::public.curated_course_node_type, 'Natural selection', null, 0),
  ('dbdb630a-700d-4526-a5af-42fe5f0340f9', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'd39f372d-6742-4b9d-8ead-0cc830239dda', 'concept'::public.curated_course_node_type, 'Inheritance and population variation', null, 1),
  ('75f71977-06fb-4397-9aef-01faae462afe', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'd39f372d-6742-4b9d-8ead-0cc830239dda', 'concept'::public.curated_course_node_type, 'Adaptation', null, 2),
  ('c3ceccb3-927e-4af9-94cc-4b61960c402d', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'd39f372d-6742-4b9d-8ead-0cc830239dda', 'concept'::public.curated_course_node_type, 'Gene-culture interaction', null, 3),
  ('6c29c9b7-5908-4472-813f-fd5a4035c997', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'c7eb4f97-8ee2-4331-849a-aa4a58e0b8e9', 'subtopic'::public.curated_course_node_type, 'Primates and Human Origins', 'The gist is understanding humans in relation to other primates and fossil evidence.', 1),
  ('1c4f6a1a-cf30-4904-a34a-c709f56a5412', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '6c29c9b7-5908-4472-813f-fd5a4035c997', 'concept'::public.curated_course_node_type, 'Primate taxonomy and behavior', null, 0),
  ('6f0c4fdf-237a-476b-9343-1159af21c58f', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '6c29c9b7-5908-4472-813f-fd5a4035c997', 'concept'::public.curated_course_node_type, 'Bipedalism', null, 1),
  ('35ed7090-bcba-4bf1-a5ed-7773d0fcedec', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '6c29c9b7-5908-4472-813f-fd5a4035c997', 'concept'::public.curated_course_node_type, 'Homo evolution', null, 2),
  ('f7ef919a-eaf8-4ba6-a4a2-730cb10516e2', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '6c29c9b7-5908-4472-813f-fd5a4035c997', 'concept'::public.curated_course_node_type, 'Migration and dispersal', null, 3),
  ('c24942f6-af7a-43e8-b90f-b6f1a321a2e4', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'c7eb4f97-8ee2-4331-849a-aa4a58e0b8e9', 'subtopic'::public.curated_course_node_type, 'Human Variation and Ethics', 'Students learn why biological variation is real but racial typology is scientifically and ethically flawed.', 2),
  ('260fbf0b-b505-46bb-b6f3-0589b844cb43', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'c24942f6-af7a-43e8-b90f-b6f1a321a2e4', 'concept'::public.curated_course_node_type, 'Clinal variation', null, 0),
  ('38eed344-ec8e-4287-9025-f00bb043b0eb', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'c24942f6-af7a-43e8-b90f-b6f1a321a2e4', 'concept'::public.curated_course_node_type, 'Skin color and adaptation', null, 1),
  ('c99439a6-9bc1-4b3f-8c3e-7bfe82583e93', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'c24942f6-af7a-43e8-b90f-b6f1a321a2e4', 'concept'::public.curated_course_node_type, 'Race as social classification', null, 2),
  ('fc3ff5f6-1860-4fba-9439-ad940d56e5d1', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'c24942f6-af7a-43e8-b90f-b6f1a321a2e4', 'concept'::public.curated_course_node_type, 'Human remains ethics', null, 3),
  ('bfa9a2e7-d360-45b3-82f4-4e4b176b63ba', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', null, 'topic'::public.curated_course_node_type, 'Archaeology, Material Evidence, Dating, and the Human Past', 'Archaeology studies the human past through material evidence. Students learn how artifacts, sites, landscapes, and dates become interpretations of human life.', 4),
  ('0ab3474e-11ee-4b93-94e0-500f36a6e44c', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', 'bfa9a2e7-d360-45b3-82f4-4e4b176b63ba', 'subtopic'::public.curated_course_node_type, 'Archaeological Evidence', 'Students learn what counts as evidence when people are not available to interview.', 0),
