  ('e7fbbc1a-ec14-42c2-a947-11da6dddbfe3', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', '7826eeb7-81da-4b95-9acc-5c0490cdcc08', 'subtopic'::public.curated_course_node_type, 'Households and Social Organization', 'The point is to analyze how groups coordinate care, work, inheritance, and residence.', 1),
