values
  ('678aecc4-cb04-49c1-87cf-312fe6da74e0', 'c3d4e5f6-7a8b-4d23-8e23-3f4a5b6c7d33', null, 'topic'::public.curated_course_node_type, 'Economy, Subsistence, Labor, Gifts, Markets, and Inequality', 'Anthropology treats economic life as social and moral life. Students compare how people produce, exchange, value, and survive.', 10),
